BEGIN;
CREATE TABLE IF NOT EXISTS public.blog_admins(user_id uuid PRIMARY KEY REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_admins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.blog_admins FROM anon, authenticated;
GRANT SELECT ON public.blog_admins TO authenticated;
DROP POLICY IF EXISTS admin_self ON public.blog_admins;
CREATE POLICY admin_self ON public.blog_admins FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.blog_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.blog_admins WHERE user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.blog_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.blog_is_admin() TO authenticated,service_role;
CREATE TABLE IF NOT EXISTS public.blog_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9][a-z0-9-]{0,99}$'), title text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', document jsonb NOT NULL DEFAULT '{"type":"doc","content":[{"type":"paragraph"}]}', category text NOT NULL DEFAULT '学习', tags text[] NOT NULL DEFAULT '{}', cover text, featured boolean NOT NULL DEFAULT false, published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS public.blog_posts(id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, excerpt text NOT NULL, document jsonb NOT NULL, category text NOT NULL, tags text[] NOT NULL, cover text, featured boolean NOT NULL DEFAULT false, published_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS public.blog_settings(id integer PRIMARY KEY CHECK(id=1), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS public.blog_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE, snapshot jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','building','live','failed','superseded')), error text, run_id bigint, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.blog_public_state(id integer PRIMARY KEY CHECK(id=1), release_id uuid REFERENCES public.blog_releases(id));
CREATE TABLE IF NOT EXISTS public.blog_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid, nickname text NOT NULL DEFAULT '访客' CHECK(char_length(nickname) BETWEEN 1 AND 30), body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS public.blog_rate_limits(client_key text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS public.blog_runtime_config(id integer PRIMARY KEY CHECK(id=1), config jsonb NOT NULL DEFAULT '{}');
INSERT INTO public.blog_settings(id,data) VALUES(1,'{"name":"Sun XT 的博客","author":"Sun XT","description":"把学习中的发现、生活里的片段，和慢慢长成的想法，留在这里。","github":"https://github.com/Sun-XT9527","about":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"你好，我是 Sun XT。这里是我的个人记录空间。关于我的更多介绍，正在慢慢整理中。"}]}]},"projects":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.blog_public_state(id) VALUES(1) ON CONFLICT DO NOTHING;
INSERT INTO public.blog_runtime_config(id) VALUES(1) ON CONFLICT DO NOTHING;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['blog_drafts','blog_posts','blog_settings','blog_releases','blog_public_state','blog_messages','blog_rate_limits','blog_runtime_config'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);END LOOP;FOREACH t IN ARRAY ARRAY['blog_drafts','blog_settings'] LOOP EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t);EXECUTE format('DROP POLICY IF EXISTS blog_admin_all ON public.%I',t);EXECUTE format('CREATE POLICY blog_admin_all ON public.%I TO authenticated USING(public.blog_is_admin()) WITH CHECK(public.blog_is_admin())',t);END LOOP;FOREACH t IN ARRAY ARRAY['blog_posts','blog_releases'] LOOP EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('DROP POLICY IF EXISTS blog_admin_read ON public.%I',t);EXECUTE format('CREATE POLICY blog_admin_read ON public.%I FOR SELECT TO authenticated USING(public.blog_is_admin())',t);END LOOP;END $$;
GRANT ALL ON public.blog_admins TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.blog_releases_sequence_seq TO service_role;
GRANT SELECT ON public.blog_messages TO anon,authenticated;
GRANT UPDATE ON public.blog_messages TO authenticated;
CREATE OR REPLACE FUNCTION public.blog_post_is_live(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.blog_public_state s JOIN public.blog_releases r ON r.id=s.release_id CROSS JOIN LATERAL jsonb_array_elements(r.snapshot->'posts') p WHERE p->>'id'=p_id::text) $$;
REVOKE ALL ON FUNCTION public.blog_post_is_live(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.blog_post_is_live(uuid) TO anon,authenticated,service_role;
DROP POLICY IF EXISTS messages_public_read ON public.blog_messages;
CREATE POLICY messages_public_read ON public.blog_messages FOR SELECT TO anon,authenticated USING(deleted_at IS NULL AND (post_id IS NULL OR public.blog_post_is_live(post_id)));
DROP POLICY IF EXISTS messages_admin_read ON public.blog_messages;
CREATE POLICY messages_admin_read ON public.blog_messages FOR SELECT TO authenticated USING(public.blog_is_admin());
DROP POLICY IF EXISTS messages_admin_update ON public.blog_messages;
CREATE POLICY messages_admin_update ON public.blog_messages FOR UPDATE TO authenticated USING(public.blog_is_admin()) WITH CHECK(public.blog_is_admin());
CREATE OR REPLACE FUNCTION public.blog_get_live_snapshot() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT COALESCE((SELECT r.snapshot FROM public.blog_public_state s JOIN public.blog_releases r ON r.id=s.release_id WHERE s.id=1),'{"settings":{"name":"Sun XT 的博客","author":"Sun XT","description":"把学习中的发现、生活里的片段，和慢慢长成的想法，留在这里。","github":"https://github.com/Sun-XT9527","about":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"你好，我是 Sun XT。这里是我的个人记录空间。关于我的更多介绍，正在慢慢整理中。"}]}]},"projects":[]},"posts":[]}'::jsonb) $$;
CREATE OR REPLACE FUNCTION public.blog_get_build_snapshot(p_release_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT snapshot FROM public.blog_releases WHERE id=p_release_id AND status IN ('queued','building','live') $$;
REVOKE ALL ON FUNCTION public.blog_get_live_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.blog_get_build_snapshot(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.blog_get_live_snapshot(),public.blog_get_build_snapshot(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.blog_add_message(p_client_key text,p_nickname text,p_body text,p_post_id uuid DEFAULT NULL) RETURNS public.blog_messages LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE row public.blog_messages; attempts integer; BEGIN
 IF char_length(trim(p_body)) NOT BETWEEN 1 AND 1000 OR char_length(p_nickname)>30 OR char_length(p_client_key)<>64 THEN RAISE EXCEPTION 'invalid_message';END IF;
 IF p_post_id IS NOT NULL AND NOT public.blog_post_is_live(p_post_id) THEN RAISE EXCEPTION 'article_not_live';END IF;
 INSERT INTO public.blog_rate_limits(client_key,window_start,count) VALUES(p_client_key,date_trunc('minute',clock_timestamp()),1) ON CONFLICT(client_key) DO UPDATE SET count=CASE WHEN blog_rate_limits.window_start=date_trunc('minute',clock_timestamp()) THEN blog_rate_limits.count+1 ELSE 1 END,window_start=date_trunc('minute',clock_timestamp()) RETURNING count INTO attempts;
 IF attempts>3 THEN RAISE EXCEPTION 'rate_limited';END IF;
 DELETE FROM public.blog_rate_limits WHERE window_start<now()-interval '1 day';
 INSERT INTO public.blog_messages(post_id,nickname,body) VALUES(p_post_id,COALESCE(NULLIF(trim(p_nickname),''),'访客'),trim(p_body)) RETURNING * INTO row;RETURN row;
 END $$;
REVOKE ALL ON FUNCTION public.blog_add_message(text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.blog_add_message(text,text,text,uuid) TO service_role;
DROP FUNCTION IF EXISTS public.blog_create_release(text,uuid,jsonb);
CREATE OR REPLACE FUNCTION public.blog_create_release(p_action text,p_id uuid DEFAULT NULL,p_post jsonb DEFAULT NULL,p_settings jsonb DEFAULT NULL) RETURNS public.blog_releases LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result public.blog_releases;release_id uuid=gen_random_uuid(); BEGIN
 PERFORM pg_advisory_xact_lock(701953);
 IF p_action='publish' THEN
 INSERT INTO public.blog_posts(id,slug,title,excerpt,document,category,tags,cover,featured,published_at,updated_at) SELECT p_id,p_post->>'slug',p_post->>'title',p_post->>'excerpt',p_post->'document',p_post->>'category',ARRAY(SELECT jsonb_array_elements_text(p_post->'tags')),NULLIF(p_post->>'cover',''),COALESCE((p_post->>'featured')::boolean,false),COALESCE((SELECT published_at FROM public.blog_posts WHERE id=p_id),now()),now() ON CONFLICT(id) DO UPDATE SET slug=EXCLUDED.slug,title=EXCLUDED.title,excerpt=EXCLUDED.excerpt,document=EXCLUDED.document,category=EXCLUDED.category,tags=EXCLUDED.tags,cover=EXCLUDED.cover,featured=EXCLUDED.featured,updated_at=now();
 UPDATE public.blog_drafts SET published_at=(SELECT published_at FROM public.blog_posts WHERE id=p_id) WHERE id=p_id;
 ELSIF p_action IN ('unpublish','delete') THEN DELETE FROM public.blog_posts WHERE id=p_id;UPDATE public.blog_drafts SET published_at=NULL,deleted_at=CASE WHEN p_action='delete' THEN now() ELSE deleted_at END WHERE id=p_id;
 ELSIF p_action NOT IN ('settings','retry') THEN RAISE EXCEPTION 'invalid_action';END IF;
 INSERT INTO public.blog_releases(id,snapshot) SELECT release_id,jsonb_build_object('revision',release_id,'created_at',now(),'settings',COALESCE(p_settings,(SELECT data FROM public.blog_settings WHERE id=1)),'posts',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY published_at DESC) FROM public.blog_posts p),'[]'::jsonb)) RETURNING * INTO result;RETURN result;
 END $$;
REVOKE ALL ON FUNCTION public.blog_create_release(text,uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.blog_create_release(text,uuid,jsonb,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.blog_finish_release(p_id uuid,p_status text,p_error text DEFAULT NULL,p_run_id bigint DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE seq bigint;active_seq bigint;BEGIN
 PERFORM pg_advisory_xact_lock(701953);
 IF p_status NOT IN ('live','failed','building') THEN RAISE EXCEPTION 'invalid_status';END IF;
 UPDATE public.blog_releases SET status=p_status,error=left(p_error,1000),run_id=p_run_id,completed_at=CASE WHEN p_status IN ('live','failed') THEN now() ELSE NULL END WHERE id=p_id RETURNING sequence INTO seq;
 IF seq IS NULL THEN RAISE EXCEPTION 'release_missing';END IF;
 SELECT r.sequence INTO active_seq FROM public.blog_public_state s JOIN public.blog_releases r ON r.id=s.release_id WHERE s.id=1;
 IF p_status='live' AND (active_seq IS NULL OR seq>active_seq) THEN UPDATE public.blog_releases SET status='superseded' WHERE status='live' AND id<>p_id;UPDATE public.blog_public_state SET release_id=p_id WHERE id=1;ELSIF p_status='live' THEN UPDATE public.blog_releases SET status='superseded' WHERE id=p_id;END IF;
 END $$;
REVOKE ALL ON FUNCTION public.blog_finish_release(uuid,text,text,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.blog_finish_release(uuid,text,text,bigint) TO service_role;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('blog-drafts','blog-drafts',false,5242880,ARRAY['image/jpeg','image/png','image/webp','image/gif']),('blog-public','blog-public',true,5242880,ARRAY['image/jpeg','image/png','image/webp','image/gif']) ON CONFLICT(id) DO NOTHING;
DROP POLICY IF EXISTS blog_image_admin ON storage.objects;
CREATE POLICY blog_image_admin ON storage.objects TO authenticated USING(bucket_id IN ('blog-drafts','blog-public') AND public.blog_is_admin()) WITH CHECK(bucket_id='blog-drafts' AND public.blog_is_admin());
NOTIFY pgrst,'reload schema';
COMMIT;
